import type { MetadataRoute } from "next";

/**
 * Web app manifest — makes ScheduleAI installable (Add to Home Screen on
 * iOS, "Install app" on Android/Chrome). On iPhone this is what unlocks
 * Web Push: iOS only exposes the Push API to INSTALLED home-screen web
 * apps (iOS 16.4+), never to a plain Safari tab.
 *
 * The icons are generated by scripts/generate-icons.mjs (no image deps).
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "ScheduleAI — your week, sorted",
    short_name: "ScheduleAI",
    description:
      "Photograph a timetable, add work shifts, deadlines and personal blocks, and get one editable weekly plan with clash detection, reminders and calendar export.",
    start_url: "/dashboard",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#0a0b10",
    theme_color: "#6366f1",
    icons: [
      { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
